/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { SpeedDialButtonComponent } from './speed-dial-button.component';

describe('SpeedDialButtonComponent', () => {
  it('emits click and toggles parent', () => {
    TestBed.configureTestingModule({
      imports: [SpeedDialButtonComponent],
    });

    const fixture = TestBed.createComponent(SpeedDialButtonComponent);
    const component = fixture.componentInstance;
    const emitted = jasmine.createSpy('emitted');
    const parent = { toggleFab: jasmine.createSpy('toggleFab') };
    (component as any).parent = parent;

    component.click.subscribe(emitted);

    const event = {
      preventDefault: jasmine.createSpy('preventDefault'),
      stopPropagation: jasmine.createSpy('stopPropagation'),
    } as unknown as Event;

    component.onClick(event);

    expect(event.preventDefault).toHaveBeenCalled();
    expect(event.stopPropagation).toHaveBeenCalled();
    expect(emitted).toHaveBeenCalled();
    expect(parent.toggleFab).toHaveBeenCalled();
  });
});
